public class PlatformServiceSmokeTest { public static void main(String[] args){PlatformService s=new PlatformService(new Repositories(),new OpenAiVisionService(new OpenAiConfig("","https://api.openai.com/v1","gpt-5.2",false))); var auth=s.register(new Requests.Register("u@example.com","secret","User",Set.of(Role.USER))); s.purchase(auth.userId(),new Requests.Purchase("BASIC",5,BigDecimal.valueOf(9.99))); var a=s.upload(new Requests.UploadAnalysis(auth.userId(),"FUNDUS",List.of(new Requests.ImageInput("left.jpg","image/jpeg",1000)))); if(a.findings().isEmpty()||s.history(auth.userId()).isEmpty()) throw new AssertionError("workflow failed"); System.out.println("SMOKE_OK "+a.riskLevel());}}
